INSERT INTO questions (qid, stem, stem_blocks, hint, subject, syllabus_version, theme, cognitive_level, difficulty_band, status, provenance) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', 'Which statement about the three states of matter is correct?', '[{"type": "text", "text": "Which statement about the three states of matter is correct?", "src": "", "alt": "", "header": [], "rows": []}]'::jsonb, 'Think about which states keep a fixed shape and which keep a fixed volume.', 'Science', '2023', 'Cycles', 'comprehension', 'core', 'answered', 'ingested') ON CONFLICT (qid) DO UPDATE SET stem=EXCLUDED.stem, stem_blocks=EXCLUDED.stem_blocks, hint=EXCLUDED.hint;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', '1', 'A gas has no mass.', NULL, false, 'Incorrect. Gases do have mass, even though it is small and they are often invisible.', 'Gases do not have mass.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', '2', 'A liquid takes the shape of its container but has a fixed volume.', NULL, true, 'Correct. A liquid flows to take the shape of its container while its volume stays fixed.', NULL) ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', '3', 'A solid changes its volume to fill its container.', NULL, false, 'Incorrect. A solid keeps a fixed shape and volume; it does not expand to fill a container.', 'A solid can change its volume to fit a container.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', '4', 'A liquid has its own fixed shape.', NULL, false, 'Incorrect. A liquid has no fixed shape; it takes the shape of its container.', 'A liquid has a fixed shape.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-1:160500492e', 'concept', 'states of matter') ON CONFLICT DO NOTHING;
