INSERT INTO questions (qid, stem, stem_blocks, hint, subject, syllabus_version, theme, cognitive_level, difficulty_band, status, provenance) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', 'A bar magnet is brought near several objects. Which statement is correct?', '[{"type": "text", "text": "A bar magnet is brought near several objects. Which statement is correct?", "src": "", "alt": "", "header": [], "rows": []}]'::jsonb, 'Recall which materials are magnetic and what like/unlike poles do.', 'Science', '2023', 'Interactions', 'knowledge', 'foundational', 'answered', 'ingested') ON CONFLICT (qid) DO UPDATE SET stem=EXCLUDED.stem, stem_blocks=EXCLUDED.stem_blocks, hint=EXCLUDED.hint;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', '1', 'The magnet attracts all metals, including aluminium.', NULL, false, 'Incorrect. Magnets attract only magnetic materials (iron, steel); aluminium is not attracted.', 'A magnet attracts all metals.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', '2', 'A bigger magnet is always stronger than a smaller magnet.', NULL, false, 'Incorrect. Strength depends on the magnet, not merely its size; a small magnet can be stronger.', 'A larger magnet is always stronger than a smaller one.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', '3', 'The magnet can exert a push or a pull on magnetic materials.', NULL, true, 'Correct. A magnet exerts a push (repulsion) or a pull (attraction) on magnetic materials.', NULL) ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', '4', 'Two north poles placed together will attract each other.', NULL, false, 'Incorrect. Like poles repel; only unlike poles attract.', 'Like poles attract each other.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', 'concept', 'magnetic force') ON CONFLICT DO NOTHING;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', 'concept', 'magnetic materials') ON CONFLICT DO NOTHING;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-2:ba12904012', 'concept', 'magnetic poles') ON CONFLICT DO NOTHING;
INSERT INTO questions (qid, stem, stem_blocks, hint, subject, syllabus_version, theme, cognitive_level, difficulty_band, status, provenance) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', 'In a circuit with a battery, wires and a bulb, the bulb does not light up. Which is the most likely reason?', '[{"type": "text", "text": "In a circuit with a battery, wires and a bulb, the bulb does not light up. Which is the most likely reason?", "src": "", "alt": "", "header": [], "rows": []}]'::jsonb, 'A bulb only lights when current can flow all the way round.', 'Science', '2023', 'Systems', 'application', 'core', 'answered', 'ingested') ON CONFLICT (qid) DO UPDATE SET stem=EXCLUDED.stem, stem_blocks=EXCLUDED.stem_blocks, hint=EXCLUDED.hint;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', '1', 'The circuit is open at one point.', NULL, true, 'Correct. A break (open) anywhere in the circuit stops the current, so the bulb will not light.', NULL) ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', '2', 'Current is used up by the bulb so none returns to the battery.', NULL, false, 'Incorrect. Current is not used up; the same current flows through the whole series circuit.', 'Electric current is used up by the bulb so less returns to the battery.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', '3', 'The bulb can only light in an open circuit.', NULL, false, 'Incorrect. A bulb lights only in a closed circuit, not an open one.', 'A bulb lights up even in an open circuit.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', '4', 'Plastic wires conduct the electricity away.', NULL, false, 'Incorrect. Plastic is an insulator; it does not conduct electricity away.', 'Plastic is a good conductor of electricity.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', 'concept', 'electric circuit') ON CONFLICT DO NOTHING;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', 'concept', 'closed circuit') ON CONFLICT DO NOTHING;
INSERT INTO question_tags (qid, kind, value) VALUES ('question:science-2023-sample-sci-2023-3:bda4e22395', 'concept', 'electrical conductor') ON CONFLICT DO NOTHING;
INSERT INTO questions (qid, stem, stem_blocks, hint, subject, syllabus_version, theme, cognitive_level, difficulty_band, status, provenance) VALUES ('question:science-2023-sample-sci-2023-4:e1b396be5a', 'The table shows whether four objects are attracted to a magnet. Which object is most likely made of a magnetic material?', '[{"type": "text", "text": "The table shows whether four objects are attracted to a magnet. Which object is most likely made of a magnetic material?", "src": "", "alt": "", "header": [], "rows": []}, {"type": "table", "text": "", "src": "", "alt": "", "header": ["Object", "Attracted to magnet?"], "rows": [["W", "No"], ["X", "Yes"], ["Y", "No"], ["Z", "No"]]}]'::jsonb, 'Only magnetic materials are attracted to a magnet.', 'Science', '2023', 'Interactions', 'application', 'core', 'answered', 'ingested') ON CONFLICT (qid) DO UPDATE SET stem=EXCLUDED.stem, stem_blocks=EXCLUDED.stem_blocks, hint=EXCLUDED.hint;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-4:e1b396be5a', '1', 'W', NULL, false, 'Incorrect. W is not attracted to the magnet, so it is not magnetic.', 'An object that is not attracted to a magnet is still magnetic.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-4:e1b396be5a', '2', 'X', NULL, true, 'Correct. X is attracted to the magnet, so it is most likely a magnetic material.', NULL) ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-4:e1b396be5a', '3', 'Y', NULL, false, 'Incorrect. Y is not attracted to the magnet, so it is not magnetic.', 'An object that is not attracted to a magnet is still magnetic.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
INSERT INTO options (qid, label, text, image, is_correct, rationale, misconception) VALUES ('question:science-2023-sample-sci-2023-4:e1b396be5a', '4', 'Z', NULL, false, 'Incorrect. Z is not attracted to the magnet, so it is not magnetic.', 'An object that is not attracted to a magnet is still magnetic.') ON CONFLICT (qid, label) DO UPDATE SET text=EXCLUDED.text, image=EXCLUDED.image, is_correct=EXCLUDED.is_correct, rationale=EXCLUDED.rationale;
